(()=>{
"use strict";
const $=s=>document.querySelector(s), esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem("resumate."+k))??d}catch{return d}},write=(k,v)=>localStorage.setItem("resumate."+k,JSON.stringify(v));
let data=null,tab="recommended",busy=false;
const list=(key)=>read(key,[]), saved=id=>list("savedJobs").includes(id), applied=id=>list("appliedJobs").includes(id);
const style=`<style>
.job-controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:9px;margin:16px 0}.job-controls input,.job-controls select{min-width:0;background:var(--card);color:var(--txt);border:1px solid var(--line);border-radius:9px;padding:10px;font:inherit}.job-tabs{display:flex;gap:8px;overflow:auto;padding:4px 0 10px}.job-tabs button{white-space:nowrap}.job-card{display:grid;grid-template-columns:46px minmax(0,1fr) minmax(74px,max-content);align-items:start;gap:14px;padding:17px;margin:10px 0;background:var(--card);border:1px solid var(--line);border-radius:14px;min-width:0}.job-card>div:nth-child(2){min-width:0;overflow-wrap:anywhere}.job-score{min-width:74px;max-width:120px}.job-score .mut{max-width:120px;line-height:1.3;white-space:normal;overflow-wrap:anywhere}.job-logo{width:46px;height:46px;border-radius:10px;background:var(--bg);display:grid;place-items:center;font-weight:800;color:var(--lav);overflow:hidden}.job-logo img{width:100%;height:100%;object-fit:contain}.job-card h3{margin:0;font-size:17px}.job-meta{color:var(--mut);font-size:13px;margin:4px 0}.job-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.job-score{font-weight:800;color:var(--ok);font-size:18px;text-align:right}.job-card details{margin:9px 0}.job-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px}.job-stat{padding:13px;background:var(--bg);border-radius:10px}.job-stat b{font-size:22px;display:block}.job-error{padding:14px;border:1px solid var(--bad);border-radius:10px;color:var(--bad)}@media(max-width:580px){.job-card{grid-template-columns:38px 1fr}.job-logo{width:38px;height:38px}.job-score{grid-column:2;text-align:left}.job-card .job-actions{grid-column:1/-1}}
</style>`;
function shell(){return `${style}<div class="row" style="justify-content:space-between;align-items:center"><div><h1 style="margin:8px 0 0">Job Discovery</h1><p class="mut">Real vacancies from public job boards and configured company career pages.</p></div><button class="btn" data-jobs="refresh">Refresh listings</button></div><div id="job-profile" class="card" style="margin:16px 0"></div><div id="job-analytics"></div><div class="job-controls"><input id="jf-role" placeholder="Role"><input id="jf-company" placeholder="Company"><input id="jf-location" placeholder="Location"><select id="jf-work"><option value="">Any workplace</option><option value="remote">Remote</option><option value="onsite">On-site / hybrid</option></select><select id="jf-type"><option value="">Any job type</option><option>Internship</option><option>Full-time</option><option>Contract</option></select><select id="jf-level"><option value="">Any experience</option><option value="fresher">Fresher / entry-level</option></select><input id="jf-salary" type="number" min="0" placeholder="Min salary / stipend"><input id="jf-skill" placeholder="Required skill"><button class="btn pri" data-jobs="filter">Apply filters</button></div><div class="job-tabs">${[["recommended","Recommended for You"],["latest","Latest Jobs"],["internships","Internship Opportunities"],["fresher","Fresher Jobs"],["remote","Remote Jobs"],["company","Jobs by Company"],["saved","Saved Jobs"],["applied","Applied Jobs"]].map(([k,v])=>`<button class="btn ${tab===k?"pri":""}" data-tab="${k}">${v}</button>`).join("")}</div><div id="job-sources" class="mut" style="font-size:12px;margin-bottom:8px"></div><div id="job-results"><div class="card">Loading live job listings…</div></div>`}
function profileCard(p){if(!p)return `<b>Resume profile not saved yet.</b> <span class="mut">Run an analysis or paste a resume in Analyzer once to create your profile.</span> <button class="btn sm" data-go="analyze">Open Analyzer</button>`;return `<div class="row" style="justify-content:space-between"><div><b>Your saved candidate profile</b><div class="mut">${esc(p.level)}${p.education?" · "+esc(p.education):""}</div></div><button class="btn sm" data-go="analyze">Update resume</button></div><div style="margin-top:8px">${(p.technologies||[]).map(x=>`<span class="chip ok">${esc(x)}</span>`).join("")||"No recognized skills yet"}</div><div class="mut" style="font-size:12px">Stored on this device so you do not need to upload again. This app has no account or database sync.</div>`}
function analytics(a){if(!a)return "";const pills=[ ["Available jobs",a.total],["Profile matches",a.matching],["Companies hiring",a.companies],["Internships",a.internships] ];return `<div class="job-stats">${pills.map(([n,v])=>`<div class="job-stat"><span class="mut">${n}</span><b>${Number(v)||0}</b></div>`).join("")}</div><div class="grid" style="margin-top:10px"><div class="card"><h3>Most demanded skills</h3><div>${(a.mostDemandedSkills||[]).map(x=>`<span class="chip">${esc(x.skill)} · ${x.count}</span>`).join("")||"No skills reported by sources"}</div></div><div class="card"><h3>Common job roles</h3><div>${(a.commonRoles||[]).map(x=>`<span class="chip">${esc(x.role)} · ${x.count}</span>`).join("")||"No roles reported"}</div></div></div>`}
document.head.insertAdjacentHTML("beforeend",`<style>.job-source-credit{display:inline-flex;min-width:116px;min-height:23px;align-items:center}.job-trend{display:grid;grid-template-columns:120px 1fr;gap:8px;align-items:center;margin:5px 0}.job-trend-bar{display:flex;gap:2px;align-items:end;height:28px}.job-trend-bar i{display:block;flex:1;min-width:8px;background:var(--blue);border-radius:3px 3px 0 0;opacity:.8}</style>`);
function analytics(a){if(!a)return "";const pills=[["Available jobs",a.total],["Profile matches",a.matching],["Companies hiring",a.companies],["Internships",a.internships]];return `<div class="job-stats">${pills.map(([n,v])=>`<div class="job-stat"><span class="mut">${n}</span><b>${Number(v)||0}</b></div>`).join("")}</div><div class="grid" style="margin-top:10px"><div class="card"><h3>Most demanded skills</h3><div>${(a.mostDemandedSkills||[]).map(x=>`<span class="chip">${esc(x.skill)} · ${x.count}</span>`).join("")||"No skills reported by sources"}</div></div><div class="card"><h3>Common job roles</h3><div>${(a.commonRoles||[]).map(x=>`<span class="chip">${esc(x.role)} · ${x.count}</span>`).join("")||"No roles reported by sources"}</div></div><div class="card"><h3>Skill demand trends</h3><div class="mut" style="font-size:12px">Listings grouped by posting month</div>${(a.skillDemandTrends||[]).map(t=>{const max=Math.max(1,...t.months.map(m=>m.count));return `<div class="job-trend"><b>${esc(t.skill)}</b><div class="job-trend-bar">${t.months.map(m=>`<i title="${esc(m.month)}: ${m.count}" style="height:${Math.max(3,Math.round(m.count/max*26))}px"></i>`).join("")}</div></div>`}).join("")||"No dated listings to chart"}</div></div>`}
function date(s){if(!s)return "Date not provided";const d=new Date(s);return Number.isNaN(+d)?"Date not provided":d.toLocaleDateString(undefined,{year:"numeric",month:"short",day:"numeric"})}
function card(j){const req=(j.skills||[]);return `<article class="job-card"><div class="job-logo">${j.companyLogo?`<img src="${esc(j.companyLogo)}" alt="" onerror="this.remove();this.parentNode.textContent='${esc(j.company.slice(0,2).toUpperCase())}'">`:esc(j.company.slice(0,2).toUpperCase())}</div><div><h3>${esc(j.title)}</h3><div class="job-meta">${esc(j.company)} · ${esc(j.location)} · ${esc(j.workplace)}<br>${esc(j.experienceRequirement)} · ${esc(j.jobType)} · ${esc(j.salary||"Salary not listed")} · Posted ${date(j.postedAt)}</div><div class="job-meta">Source: <b>${esc(j.sourceLabel)}</b></div>${req.length?`<details><summary>Required skills (${req.length}) · ${j.matchedSkills?.length||0} matched · ${j.missingSkills?.length||0} missing</summary><div>Matching: ${(j.matchedSkills||[]).map(x=>`<span class="chip ok">${esc(x)}</span>`).join("")||"None identified"}</div><div>Missing: ${(j.missingSkills||[]).map(x=>`<span class="chip bad">${esc(x)}</span>`).join("")||"None identified"}</div></details>`:"<div class='mut'>Source did not provide recognizable skill requirements.</div>"}<div class="job-actions"><a class="btn pri" href="${esc(j.applicationUrl)}" target="_blank" rel="noopener noreferrer">Apply at source</a><button class="btn" data-jobs="save" data-id="${esc(j.id)}">${saved(j.id)?"Saved ✓":"Save job"}</button><button class="btn" data-jobs="applied" data-id="${esc(j.id)}">${applied(j.id)?"Applied ✓":"Mark applied"}</button></div></div><div class="job-score">${j.score==null?"—":j.score+"%"}<div class="mut" style="font-size:11px;font-weight:400">resume match</div></div></article>`}
function card(j){const req=j.skills||[],credit=j.sourceUrl?`<a class="job-source-credit" href="${esc(j.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(j.sourceLabel)}</a>`:`<b>${esc(j.sourceLabel)}</b>`;return `<article class="job-card"><div class="job-logo">${j.companyLogo?`<img src="${esc(j.companyLogo)}" alt="" onerror="this.remove();this.parentNode.textContent='${esc(j.company.slice(0,2).toUpperCase())}'">`:esc(j.company.slice(0,2).toUpperCase())}</div><div><h3>${esc(j.title)}</h3><div class="job-meta">${esc(j.company)} · ${esc(j.location)} · ${esc(j.workplace)}<br>${esc(j.experienceRequirement)} · ${esc(j.jobType)} · ${esc(j.salary||"Salary not listed")} · Posted ${date(j.postedAt)}</div><div class="job-meta">Source: ${credit}</div>${req.length?`<details><summary>Required skills (${req.length}) · ${j.matchedSkills?.length||0} matched · ${j.missingSkills?.length||0} missing</summary><div>Matching: ${(j.matchedSkills||[]).map(x=>`<span class="chip ok">${esc(x)}</span>`).join("")||"None identified"}</div><div>Missing: ${(j.missingSkills||[]).map(x=>`<span class="chip bad">${esc(x)}</span>`).join("")||"None identified"}</div></details>`:"<div class='mut'>Source did not provide recognizable skill requirements.</div>"}<div class="job-actions"><a class="btn pri" href="${esc(j.applicationUrl)}" target="_blank" rel="noopener noreferrer">Apply at source</a><button class="btn" data-jobs="save" data-id="${esc(j.id)}">${saved(j.id)?"Saved ✓":"Save job"}</button><button class="btn" data-jobs="applied" data-id="${esc(j.id)}">${applied(j.id)?"Applied ✓":"Mark applied"}</button></div></div><div class="job-score">${j.score==null?"—":j.score+"%"}<div class="mut" style="font-size:11px;font-weight:400">resume match</div></div></article>`}
function render(){const e=$("#job-results");if(!data)return;let jobs=data.jobs||[];if(tab==="internships")jobs=jobs.filter(j=>j.jobType==="Internship");if(tab==="fresher")jobs=jobs.filter(j=>/fresher|entry|intern/i.test(j.experienceRequirement));if(tab==="remote")jobs=jobs.filter(j=>j.remote);if(tab==="saved")jobs=jobs.filter(j=>saved(j.id));if(tab==="applied")jobs=jobs.filter(j=>applied(j.id));if(tab==="latest")jobs=[...jobs].sort((a,b)=>Date.parse(b.postedAt||0)-Date.parse(a.postedAt||0));if(tab==="company")jobs=[...jobs].sort((a,b)=>a.company.localeCompare(b.company));if(tab==="recommended")jobs=jobs.filter(j=>(j.score||0)>=15);
$("#job-sources").innerHTML=`Sources checked: ${(data.sources||[]).map(s=>`${esc(s.name)} ${s.ok?`(${s.count})`:"(temporarily unavailable)"}`).join(" · ")||"none"} · Updated ${date(data.updatedAt)}${data.sourceErrors?.length?` · ${data.sourceErrors.length} source(s) unavailable`:""}`;
e.innerHTML=jobs.length?jobs.map(card).join(""):`<div class="card">${tab==="saved"||tab==="applied"?"No jobs in this list yet.":"No live listings match these filters. Try broadening your search or refresh."}</div>`}
const renderBase=render;render=()=>{renderBase();document.querySelectorAll(".job-logo img").forEach(img=>{img.removeAttribute("onerror");img.addEventListener("error",()=>img.remove(),{once:true})});document.querySelectorAll(".job-card").forEach(node=>{const j=data?.jobs?.find(x=>x.id===node.querySelector("[data-id]")?.dataset.id);if(!j)return;const d=document.createElement("div");d.className="mut";d.style.fontSize="11px";d.textContent=`Score method: ${j.scoreBreakdown?.formula||"recognized skill and role signals"}; ${j.scoreBreakdown?.skillsMatched||0}/${j.scoreBreakdown?.skillsRequired||0} required skills matched`;node.querySelector(".job-score")?.appendChild(d)})};
const profileBase=profileCard;profileCard=p=>{if(!p)return profileBase(p);return profileBase(p)+`<div style="margin-top:7px"><b>Suggested role titles:</b> ${(p.roles||[]).map(x=>`<span class="chip">${esc(x)}</span>`).join("")}</div><div class="mut" style="font-size:12px;margin-top:6px">Experience: ${esc(p.experience||"Not detected")}<br>Projects: ${esc(p.projects||"Not detected")}</div>`};
function filters(){return{role:$("#jf-role").value.trim(),company:$("#jf-company").value.trim(),location:$("#jf-location").value.trim(),remote:$("#jf-work").value==="remote",workplace:["Hybrid","On-site"].includes($("#jf-work").value)?$("#jf-work").value:"",jobType:$("#jf-type").value,level:$("#jf-level").value,minSalary:$("#jf-salary").value,skill:$("#jf-skill").value.trim()}}
async function load(refresh=false){if(busy)return;busy=true;const out=$("#job-results");if(out)out.innerHTML='<div class="card">Loading live job listings from configured sources…</div>';try{const resume=read("resumeText","");const r=await fetch("/api/jobs/search"+(refresh?"?refresh=1":""),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({resume,filters:filters()})});const d=await r.json();if(!r.ok)throw Error(d.error||"Could not load jobs");data=d;if($("#job-profile"))$("#job-profile").innerHTML=profileCard(d.profile);if($("#job-analytics"))$("#job-analytics").innerHTML=analytics(d.analytics);render()}catch(e){if(out)out.innerHTML=`<div class="job-error">${esc(e.message)}. Please retry in a moment.</div>`}finally{busy=false}}
function mount(){tab="recommended";document.querySelector("#app").innerHTML=shell();const w=$("#jf-work"),old=w.querySelector('option[value="onsite"]');old.value="";old.textContent="On-site / hybrid";w.insertAdjacentHTML("beforeend",'<option value="Hybrid">Hybrid</option><option value="On-site">On-site</option>');load()}
document.addEventListener("click",e=>{const t=e.target.closest("[data-jobs],[data-tab]");if(!t)return;if(t.dataset.tab){tab=t.dataset.tab;document.querySelectorAll("[data-tab]").forEach(x=>x.classList.toggle("pri",x===t));render();return}const a=t.dataset.jobs,id=t.dataset.id;if(a==="filter")return load();if(a==="refresh")return load(true);if(a==="save"||a==="applied"){const k=a==="save"?"savedJobs":"appliedJobs",v=list(k);write(k,v.includes(id)?v.filter(x=>x!==id):[...v,id]);render()}});
window.JobDiscovery={mount,saveResume(text){if(text&&text.trim())write("resumeText",text.trim());else localStorage.removeItem("resumate.resumeText")}};
})();
